import {Store} from './store.js';import {escape,toast} from './utils.js';import {icon} from './icons.js';import {FileIO} from './fileio.js';
export const modal=document.getElementById('modal');
export function close(){modal.close()}
export function open(title,body,footer=''){modal.classList.remove('request-dialog','workspace-dialog','ata-editor-dialog');document.getElementById('modal-content').innerHTML=`<div class="modal-header"><h2>${title}</h2><button type="button" class="icon-btn" data-close aria-label="Fechar">${icon('close')}</button></div>${body}${footer}`;modal.querySelectorAll('[data-close]').forEach(b=>b.onclick=close);if(!modal.open)modal.showModal()}
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});
const input=(name,label,value='',type='text',full=false)=>`<label class="field ${full?'full':''}">${label}<input name="${name}" type="${type}" value="${escape(value)}" required ${type==='number'?'min="1" step="1"':''} maxlength="250" data-testid="field-${name}"></label>`;
const select=(name,label,options,value='',full=false)=>`<label class="field ${full?'full':''}">${label}<select name="${name}" required data-testid="field-${name}"><option value="">Selecione</option>${options.map(x=>`<option value="${escape(x)}" ${x===value?'selected':''}>${escape(x)}</option>`).join('')}</select></label>`;
export function edit(type,record,onSave){const isEdit=!!record;const r=record||{};const titles={requests:'solicitação',products:'produto',sectors:'setor',atas:'ATA de registro de preços'};let fields='';if(type==='products'){fields=input('code','Código do produto',r.code)+input('unit','Unidade de medida',r.unit)+input('product','Nome do produto',r.product,'text',true)}else if(type==='sectors'){fields=input('name','Nome do setor',r.name,'text',true)+input('responsible','Responsável',r.responsible)+input('contact','Contato (e-mail ou telefone)',r.contact)+input('ramal','Ramal',r.ramal||'')}else{fields=input('number','Número da ATA',r.number)+input('validity','Vigência até',r.validity,'date')+input('supplier','Fornecedor',r.supplier,'text',true)+input('description','Descrição',r.description,'text',true)}open(`${isEdit?'Editar':'Nova'+(type==='products'||type==='sectors'?'o':'')} ${titles[type]}`.replace('Novao','Novo'),`<form id="record-form"><div class="modal-body form-grid">${fields}<p id="form-error" role="alert" style="grid-column:1/-1;color:#c65766"></p></div><div class="modal-footer"><button class="btn" type="button" data-close>Cancelar</button><button class="btn primary" type="submit" data-testid="save-record">${icon('check')} Salvar ${titles[type].split(' ')[0]}</button></div></form>`);document.getElementById('record-form').onsubmit=e=>{e.preventDefault();let values=Object.fromEntries(new FormData(e.target));for(const k of Object.keys(values))values[k]=values[k].trim();if(Object.entries(values).some(([k,v])=>k!=='ata'&&!v))return document.getElementById('form-error').textContent='Preencha todos os campos obrigatórios.';const unique={products:'code',sectors:'name',atas:'number'}[type];if(unique&&Store.data[type].some(x=>x.id!==r.id&&x[unique].toLowerCase()===values[unique].toLowerCase()))return document.getElementById('form-error').textContent='Já existe um cadastro com esse identificador.';if(isEdit){Store.update(type,r.id,values);if(type==='sectors'){Store.data.requests.forEach(x=>{if(x.sector===r.name)x.sector=values.name});Store.save()}}else Store.add(type,values);close();toast(isEdit?'Alterações salvas.':'Cadastro criado com sucesso.');onSave()}}
export function confirmDelete(type,ids,onSave){const records=Store.data[type].filter(x=>ids.includes(x.id));if(type==='atas'&&records.some(a=>Store.data.requests.some(r=>r.ataId===a.id||r.ata===a.number)))return toast('Esta ATA possui solicitações vinculadas e deve ser mantida para preservar o histórico.');if(type==='products'&&records.some(p=>Store.data.requests.some(r=>(r.productId===p.id||r.code===p.code)&&!['Concluída','Cancelada'].includes(r.status))))return toast('Este produto possui solicitações pendentes. Atenda ou cancele os itens antes de excluir.');if(type==='sectors'&&records.some(s=>Store.data.requests.some(r=>r.sector===s.name)))return toast('Este setor possui solicitações. Remova ou transfira as solicitações primeiro.');open('Excluir registro'+(ids.length>1?'s':''),`<div class="modal-body"><p>Deseja excluir ${ids.length} registro(s)? Esta ação remove os dados salvos neste navegador.</p></div>`,`<div class="modal-footer"><button class="btn" data-close>Cancelar</button><button class="btn danger" id="confirm-delete" data-testid="confirm-delete">Excluir ${ids.length} registro(s)</button></div>`);document.getElementById('confirm-delete').onclick=()=>{Store.remove(type,ids);close();toast('Registros excluídos.');onSave()}}
export function importModal(){open('Importar catálogo de produtos',`<div class="modal-body"><p>Carregue as planilhas para adicionar produtos ao catálogo. O vínculo com uma ATA é opcional e pode ser feito agora ou depois.</p><div class="upload-zone" id="upload-zone" tabindex="0" role="button" data-testid="upload-zone">${icon('upload')}<strong>Arraste seus arquivos ou clique para selecionar</strong><small>XLS, XLSX ou CSV · Até 8 MB por arquivo</small></div><p class="hint">Colunas obrigatórias: <b>Código</b>, <b>Produto</b> e <b>Unidade de Medida</b>. Códigos iguais serão mesclados. As abas originais serão incluídas na exportação.</p><button class="subtle-link" id="template">${icon('download')} Baixar planilha modelo</button><p id="import-error" role="alert" style="color:#c65766;margin-top:15px"></p></div>`);document.getElementById('upload-zone').onclick=()=>document.getElementById('file-input').click();document.getElementById('upload-zone').onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();document.getElementById('file-input').click()}};document.getElementById('template').onclick=()=>FileIO.template();const zone=document.getElementById('upload-zone');zone.ondragover=e=>e.preventDefault();zone.ondrop=e=>{e.preventDefault();document.dispatchEvent(new CustomEvent('import-files',{detail:e.dataTransfer.files}))}}
export function importPreview(result,onDone){open('Conferir importação',`<div class="modal-body"><p><b>${result.products.length} produtos</b> encontrados em ${result.sources.length} arquivo(s). ${result.skipped?result.skipped+' linha(s) ou aba(s) sem dados válidos ignoradas.':''}</p><div class="table-scroll"><table><thead><tr><th>Código</th><th>Produto</th><th>Unidade</th></tr></thead><tbody>${result.products.slice(0,5).map(p=>`<tr><td>${escape(p.code)}</td><td>${escape(p.product)}</td><td>${escape(p.unit)}</td></tr>`).join('')}</tbody></table></div><br><label class="field">ATA de destino (opcional)<select id="import-ata"><option value="">Somente catálogo — sem vínculo com ATA</option>${Store.data.atas.map(a=>`<option value="${escape(a.id)}">${escape(a.number)}</option>`).join('')}</select></label><br><label class="field">Como importar?<select id="import-mode"><option value="merge">Adicionar / mesclar produtos</option><option value="replace" disabled>Substituir a lista de produtos desta ATA</option></select></label><p class="hint" style="margin-top:14px">Sem ATA, os produtos são adicionados ou atualizados no catálogo, preservando os vínculos existentes. Para substituir uma lista, selecione uma ATA. A substituição altera somente os vínculos de produtos da ATA escolhida. Outros cadastros e outras ATAs são mantidos. Não é possível retirar produtos com solicitações pendentes.</p><p id="import-preview-error" class="form-error" role="alert"></p></div>`,`<div class="modal-footer"><button class="btn" data-close>Cancelar</button><button class="btn primary" id="confirm-import" data-testid="confirm-import">Confirmar importação</button></div>`);document.getElementById('import-ata').onchange=()=>{const mode=document.getElementById('import-mode');const hasAta=Boolean(document.getElementById('import-ata').value);mode.querySelector('option[value=replace]').disabled=!hasAta;if(!hasAta)mode.value='merge'};document.getElementById('confirm-import').onclick=()=>{try{FileIO.commit(result,document.getElementById('import-mode').value,document.getElementById('import-ata').value)}catch(err){document.getElementById('import-preview-error').textContent=err.message;return}close();onDone()}}
